<template>
  <Button v-if="target" as-child variant="link" :class="cn('h-auto gap-1 p-0 font-normal', props.class)">
    <NuxtLink :to="docPathToRoute(target)" target="_blank" rel="noopener noreferrer">
      <CircleHelp />
      <slot>{{ label }}</slot>
    </NuxtLink>
  </Button>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue';
import { CircleHelp } from 'lucide-vue-next';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/utils';
import type { UserRole } from '~/client';
import type { DocPath } from '~/constants/pageDocs';

type DocRoleMap = Partial<Record<DocPath, UserRole | UserRole[]>>;
type DocProp = DocPath | DocRoleMap;

interface Props {
  doc: DocProp;
  label?: string;
  class?: HTMLAttributes['class'];
}

const props = withDefaults(defineProps<Props>(), {
  label: 'Help',
  class: undefined,
});

const { userRole } = useUserRole();

function resolveDocForRole(doc: DocProp, role: UserRole | undefined): DocPath | null {
  if (typeof doc === 'string') return doc;
  if (!role) return null;
  for (const [path, roles] of Object.entries(doc) as [DocPath, UserRole | UserRole[]][]) {
    if ((Array.isArray(roles) ? roles : [roles]).includes(role)) return path;
  }
  return null;
}

const target = computed(() => resolveDocForRole(props.doc, userRole.value));
</script>
