import type { RoutesNamesList } from '@typed-router';
import type { UserRole, GetDocPageData } from '~/client';

export type DocPath = GetDocPageData['path']['doc_path'];

export type RoleDoc = Partial<Record<UserRole, DocPath>>;

export const pageDocs: Partial<Record<RoutesNamesList, { roles: RoleDoc; deep?: boolean }>> = {
  users: {
    roles: {
      admin: 'guides/admin/manage-users.md',
    },
    deep: true,
  },

  account: {
    roles: {
      admin: 'guides/admin/getting-started.md',
      manager: 'guides/manager/getting-started.md',
      canvasser: 'guides/canvasser/getting-started.md',
      subcontractor_canvasser: 'guides/subcontractor_canvasser/getting-started.md',
    },
    deep: true,
  },

  shift: {
    roles: {
      canvasser: 'guides/canvasser/start-shift.md',
      subcontractor_canvasser: 'guides/subcontractor_canvasser/start-shift.md',
    },
  },

  earnings: {
    roles: {
      admin: 'guides/manager/approve-earnings.md',
      manager: 'guides/manager/approve-earnings.md',
      canvasser: 'guides/canvasser/view-earnings.md',
    },
    deep: true,
  },
  'earnings-balance': {
    roles: {
      canvasser: 'guides/canvasser/request-payout.md',
    },
    deep: true,
  },

  'coaching-feedbacks': {
    roles: {
      admin: 'guides/manager/review-coaching.md',
      manager: 'guides/manager/review-coaching.md',
    },
    deep: true,
  },

  applications: {
    roles: {
      admin: 'guides/manager/manage-assignments.md',
      manager: 'guides/manager/manage-assignments.md',
      canvasser: 'guides/canvasser/getting-started.md',
    },
    deep: true,
  },

  reports: {
    roles: {
      admin: 'guides/admin/review-fraud-reports.md',
    },
    deep: true,
  },

  'projects-id': {
    roles: {
      admin: 'guides/admin/create-project.md',
    },
    deep: true,
  },
  'projects-create': {
    roles: {
      admin: 'guides/admin/create-project.md',
    },
    deep: true,
  },
  'projects-id-applications': {
    roles: {
      admin: 'guides/manager/manage-assignments.md',
      manager: 'guides/manager/manage-assignments.md',
    },
    deep: true,
  },
};

export function resolvePageDoc(matchedNames: readonly string[], role: UserRole | undefined): DocPath | null {
  if (!role) return null;
  for (const name of matchedNames) {
    const entry = pageDocs[name as RoutesNamesList];
    if (entry && (matchedNames[0] === name || entry.deep)) return entry.roles[role] ?? null;
  }
  return null;
}
