import type { ComputedRef } from 'vue';
import { resolvePageDoc, type DocPath } from '~/constants/pageDocs';

export function usePageDoc(): ComputedRef<DocPath | null> {
  const route = useRoute();
  const { userRole } = useUserRole();

  return computed(() => {
    return resolvePageDoc(
      route.name?.split('-').map((_, i, parts) => parts.slice(0, parts.length - i).join('-')) ?? [],
      userRole.value
    );
  });
}
