<template>
  <div class="flex flex-row flex-wrap items-start justify-between gap-4">
    <div>
      <component
        :is="size === 'sm' ? 'h2' : 'h1'"
        :class="size === 'sm' ? 'font-semibold text-xl' : 'font-semibold text-3xl'"
      >
        <span v-if="showDoc && pageDoc" class="inline-flex items-center gap-2">
          <slot name="title">{{ title }}</slot>
          <DocLink :doc="pageDoc" />
        </span>
        <slot v-else name="title">{{ title }}</slot>
      </component>
      <slot name="subtitle">
        <span v-if="subtitle" class="text-accent-foreground" v-html="$marked(subtitle)" />
      </slot>
    </div>
    <div class="flex flex-row flex-wrap items-center gap-2 w-full sm:w-fit">
      <slot />
    </div>
  </div>
</template>

<script setup lang="ts">
interface Props {
  title?: string;
  subtitle?: string;
  size?: 'default' | 'sm';
  showDoc?: boolean;
}
withDefaults(defineProps<Props>(), {
  size: 'default',
  showDoc: false,
  title: undefined,
  subtitle: undefined,
});

const pageDoc = usePageDoc();
const { $marked } = useNuxtApp();
</script>

